    override val dlg_zero_telemetry_title = "Senda Datenschutzerklärung:"
    override val dlg_zero_telemetry_content = "1. Null Telemetrie: Senda sendet keinerlei Analysedaten oder Nutzungsstatistiken.\n\n2. Keine Fernstudien: Es werden keine A/B-Tests oder Experimente in Ihren Browser injiziert.\n\n3. Keine Gerätekennungen: Es wird keine eindeutige Geräte-ID erzeugt.\n\n4. Lokale Kontrolle: Ihre Lesezeichen, Passwörter und Ihr Verlauf verbleiben ausschließlich auf Ihrem Gerät."
    override val dlg_about_content = "Leichtgewichtiger, schneller und privater Webbrowser mit Mozillas GeckoView-Engine. Entwickelt für flüssiges Surfen, robuste Sicherheit und uneingeschränkten Schutz Ihrer Privatsphäre."
