    override val dlg_zero_telemetry_title = "Declaración de Privacidad Senda:"
    override val dlg_zero_telemetry_content = "1. Cero Telemetría: Senda no envía ningún paquete de datos analíticos ni métricas sobre tus hábitos.\n\n2. Cero Estudios Remotos: No se inyectan experimentos ni análisis A/B en tu navegador.\n\n3. Cero Identificadores de Dispositivo: No se genera ningún ID único para tu teléfono.\n\n4. Control Local: Tus marcadores, contraseñas e historial solo existen en tu dispositivo."
    override val dlg_about_content = "Navegador web ligero, rápido y privado con motor GeckoView de Mozilla. Diseñado para ofrecer navegación fluida, seguridad robusta y respeto total a tu privacidad."
