    override val dlg_about_third_party = "O Senda integra componentes de código aberto de classe mundial:\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• Planos de fundo de Debian, GNU, Gentoo, KDE, GNOME, Fedora, Arch e Xfce (GPL, CC BY-SA, CC0)"
    override val dlg_privacy_principles = "Princípios de Privacidade do Senda:\n\n1. Sua atenção pertence a você: Sem anúncios invasivos nem algoritmos corporativos de retenção.\n\n2. Seu dispositivo é seu: Zero telemetria oculta e zero coleta de dados encoberta.\n\n3. Web Aberta e Livre: Apoio ao software livre e a uma web descentralizada e independente."
