    override val dlg_zero_telemetry_title = "Dichiarazione sulla Privacy Senda:"
    override val dlg_zero_telemetry_content = "1. Zero Telemetria: Senda non invia alcun pacchetto di dati analitici né metriche di utilizzo.\n\n2. Nessuno Studio Remoto: Nessun esperimento A/B viene iniettato nel browser.\n\n3. Nessun Identificatore del Dispositivo: Non viene generato alcun ID univoco per il telefono.\n\n4. Controllo Locale: I tuoi segnalibri, password e cronologia risiedono esclusivamente sul tuo dispositivo."
    override val dlg_about_content = "Browser web leggero, veloce e privato con motore Mozilla GeckoView. Progettato per offrire navigazione fluida, sicurezza solida e totale rispetto per la tua privacy."
