    override val dlg_privacy_principles = "Senda プライバシー原則:\n\n1. あなたの注意はあなたのもの: 侵入的なコンテンツ、操作的な広告、ユーザー滞留アルゴリズムはありません。\n\n2. あなたの端末はあなたのもの: サイレントな遠隔測定や隠れたデータ収集は一切行いません。\n\n3. オープンで自由な Web: オープンソースソフトウェアと分散型で自立したウェブを支援します。"
