    override val dlg_about_third_party = "Senda 深度集成了世界一流的自由与开源软件组件：\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• Debian、GNU、Gentoo、KDE、GNOME、Fedora、Arch 和 Xfce 的壁纸 (GPL、CC BY-SA、CC0)"
    override val dlg_privacy_principles = "Senda 隐私核心原则：\n\n1. 您的注意力属于您自己：绝无侵入式内容、操纵性广告或旨在绑架注意力的算法。\n\n2. 您的设备由您全权做主：绝无隐蔽数据遥测，绝无后台暗中采集。\n\n3. 开放自由的网络世界：坚定拥护开源自由软件与去中心化独立互联网生态。"
