    override val audit_iv_desc = "检查每次加密都使用不同的 96 位随机 IV。"
    override val audit_iv_ok = "连续 %d 个 IV 无重复。使用 96 位随机 IV 时重复的概率可以忽略，但不为零。"
    override val audit_iv_fail = "第 %d 次加密时 IV 重复：用同一密钥重复使用 IV 会破坏 GCM 的安全性。"
    override val audit_tamper_name = "篡改检测（AEAD 标签）"
    override val audit_tamper_desc = "修改加密消息中的一位，检查其是否被拒绝。"
    override val audit_tamper_ok = "被修改的消息已被拒绝 (%s)，未返回任何解密文本。"
    override val audit_tamper_fail = "安全故障：接受了被修改的消息。"
    override val audit_wipe_name = "内存擦除"
    override val audit_wipe_desc = "检查擦除程序是否用零覆盖内容。"
    override val audit_wipe_ok = "测试缓冲区已用零覆盖。这会缩短密码在内存中停留的时间，但无法防止在使用期间进行的内存转储。"
    override val audit_wipe_fail = "内存中仍残留字符。"
    override val audit_phish_name = "域名匹配（防钓鱼）"
    override val audit_phish_desc = "检查密码只与其真实域名关联，而不会与仿冒的子域名关联。"
    override val audit_phish_ok = "全部 %d 个测试用例均得到预期结果；伪造域名未被匹配。"
    override val audit_phish_fail = "意外结果：URL=%1\$s，域名=%2\$s，预期=%3\$s，实际=%4\$s"
    override val audit_entropy_name = "密码生成器"
    override val audit_entropy_desc = "检查估计熵，以及是否包含大写、小写、数字和符号。"
    override val audit_entropy_ok = "估计熵：%s 位（最低要求：100）。包含全部四类字符。"
    override val audit_entropy_fail = "熵不足（%s 位）或缺少某类字符。"
    override val audit_verdict_ok = "自检通过：%1\$d 项中通过 %1\$d 项（并非外部认证）"
    override val audit_verdict_fail = "自检发现问题：%d 项未通过"
}

object SendaStrings {
    /** Texts in the language chosen in Senda (not the system's), for notices outside Compose. */
    fun forApp(context: Context): SendaStringPack = get(PreferencesManager(context).appLanguage, context)

    fun get(langCode: String, context: Context? = null): SendaStringPack {
        val effective = SendaLocaleManager.getEffectiveLanguage(langCode, context)
        return when (effective) {
            "DE" -> SendaStringsDe
            "EN" -> SendaStringsEn
            "ES" -> SendaStringsEs
            "FR" -> SendaStringsFr
            "PT" -> SendaStringsPt
            "IT" -> SendaStringsIt
            "JA" -> SendaStringsJa
            "ZH" -> SendaStringsZh
            else -> SendaStringsEn
        }
    }
}

val LocalSendaStrings = compositionLocalOf<SendaStringPack> { SendaStringsEs }
